import re
from datetime import datetime

_DIGITS = frozenset("0123456789")
_GMAIL_DOMAINS = frozenset({"gmail.com", "googlemail.com"})
_ANGLE_RE = re.compile(r"<([^<>]*)>")
_ZIP_PLUS4_RE = re.compile(r"^([0-9]{4,5})-[0-9]{4}$")
_DATE_FORMATS = ("%Y-%m-%dT%H:%M:%S", "%Y-%m-%d", "%m/%d/%Y")
_OPT_OUT_VALUES = frozenset({"y", "yes", "true", "1"})
_TAG_SPLIT_RE = re.compile(r"[;,]")


def _all_digits(s):
    return bool(s) and all(c in _DIGITS for c in s)


def _norm_email(raw):
    s = raw.strip()
    m = _ANGLE_RE.search(s)
    if m:
        s = m.group(1)
    s = s.strip().lower()
    if s.count("@") == 1:
        local, domain = s.split("@")
        if domain in _GMAIL_DOMAINS:
            local = local.replace(".", "").split("+", 1)[0]
            s = local + "@gmail.com"
    return s


def _valid_email(s):
    if s.count("@") != 1:
        return False
    local, domain = s.split("@")
    return (bool(local) and "." in domain
            and not domain.startswith(".") and not domain.endswith("."))


def _norm_phone(raw):
    s = raw.lower()
    cuts = [i for i in (s.find("x"), s.find("ext"), s.find("#")) if i != -1]
    if cuts:
        s = s[:min(cuts)]
    digits = "".join(c for c in s if c in _DIGITS)
    if len(digits) == 11 and digits[0] == "1":
        digits = digits[1:]
    return digits


def _valid_phone(digits):
    return len(digits) == 10 and digits[0] not in "01"


def _norm_zip(raw):
    z = raw.strip()
    m = _ZIP_PLUS4_RE.match(z)
    if m:
        z = m.group(1)
    if len(z) == 4 and _all_digits(z):
        z = "0" + z
    return z if len(z) == 5 and _all_digits(z) else ""


def _norm_name(raw):
    s = raw.strip()
    if s.isupper() or s.islower():
        s = s.title()
    return s


def _parse_updated(raw):
    s = raw.strip()
    for fmt in _DATE_FORMATS:
        try:
            return datetime.strptime(s, fmt)
        except ValueError:
            pass
    return None


def _norm_tags(raw):
    return {t.strip().lower() for t in _TAG_SPLIT_RE.split(raw) if t.strip()}


def _pick(group, field):
    """Choose a value for `field` from the group's rows where it is non-empty.
    Preference: manual source, then most recent updated, then earliest input row."""
    cands = [r for r in group if r[field]]
    if not cands:
        return ""
    cands.sort(key=lambda r: r["idx"])
    cands.sort(key=lambda r: r["ts"] if r["ts"] is not None else datetime.min,
               reverse=True)
    cands.sort(key=lambda r: not r["manual"])
    return cands[0][field]


def dedupe_contacts(rows):
    # Step 1: normalize each row and drop rows with no valid email or phone.
    recs = []
    for idx, row in enumerate(rows):
        def get(key, row=row):
            return row.get(key) or ""

        email = _norm_email(get("email"))
        if not _valid_email(email):
            email = ""
        phone = _norm_phone(get("phone"))
        if not _valid_phone(phone):
            phone = ""
        if not email and not phone:
            continue

        source = get("source").strip().lower()
        recs.append({
            "idx": idx,
            "first": _norm_name(get("first_name")),
            "last": _norm_name(get("last_name")),
            "zip": _norm_zip(get("zip")),
            "email": email,
            "phone": phone,
            "source": source,
            "manual": source == "manual",
            "tags": _norm_tags(get("tags")),
            "opted_out": get("opted_out").strip().lower() in _OPT_OUT_VALUES,
            "ts": _parse_updated(get("updated")),
        })

    # Step 2: union-find over rows that share an email, or a phone plus last name.
    parent = list(range(len(recs)))

    def find(x):
        while parent[x] != x:
            parent[x] = parent[parent[x]]
            x = parent[x]
        return x

    def union(a, b):
        ra, rb = find(a), find(b)
        if ra != rb:
            parent[rb] = ra

    email_first = {}
    phone_first = {}
    for i, r in enumerate(recs):
        if r["email"]:
            if r["email"] in email_first:
                union(i, email_first[r["email"]])
            else:
                email_first[r["email"]] = i
        if r["phone"] and r["last"]:
            key = (r["phone"], r["last"].casefold())
            if key in phone_first:
                union(i, phone_first[key])
            else:
                phone_first[key] = i

    # Step 3: group rows. Dict insertion order follows each group's earliest row.
    groups = {}
    for i, r in enumerate(recs):
        groups.setdefault(find(i), []).append(r)

    # Step 4: build one output record per person.
    output = []
    for group in groups.values():
        ts_values = [r["ts"] for r in group if r["ts"] is not None]
        all_tags = set().union(*(r["tags"] for r in group))
        output.append({
            "first_name": _pick(group, "first"),
            "last_name": _pick(group, "last"),
            "zip": _pick(group, "zip"),
            "email": _pick(group, "email"),
            "phone": _pick(group, "phone"),
            "source": _pick(group, "source"),
            "tags": ";".join(sorted(all_tags)),
            "opted_out": "Y" if any(r["opted_out"] for r in group) else "N",
            "updated": max(ts_values).strftime("%Y-%m-%d") if ts_values else "",
        })
    return output
